INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','easy','mcq','At what gestational age is the booking visit for antenatal care ideally scheduled?','["A. 28–32 weeks","B. 16–18 weeks","C. 20–24 weeks","D. Before 12 weeks"]','D','The booking visit should occur before 12 weeks gestation. It allows early screening for chromosomal anomalies, dating ultrasound, blood group/Rhesus typing, haemoglobin, VDRL, HIV, hepatitis B, and urine dipstick.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','easy','mcq','Which investigation is routinely offered at the first antenatal visit to screen for neural tube defects and Down syndrome?','["A. Amniocentesis","B. Serum alpha-fetoprotein (AFP)","C. Combined first-trimester screening (nuchal translucency + PAPP-A + free beta-hCG)","D. Chorionic villus sampling (CVS)"]','C','Combined first-trimester screening at 11–13+6 weeks uses nuchal translucency ultrasound plus maternal serum PAPP-A and free beta-hCG. It detects ~90% of trisomy 21 cases. CVS and amniocentesis are diagnostic (invasive), not screening tools.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','mcq','A 26-year-old primigravida at 20 weeks gestation attends her anomaly scan. Which finding at this scan would be MOST concerning?','["A. Placenta located anteriorly","B. Ventriculomegaly (lateral ventricle >10 mm)","C. Biparietal diameter consistent with dates","D. Three-vessel umbilical cord"]','B','The 20-week anomaly scan detects structural defects. Ventriculomegaly (lateral ventricle diameter >10 mm) is abnormal and associated with chromosomal anomalies, infection (CMV, toxoplasma), or neural tube defects. Anterior placenta and 3-vessel cord are normal findings.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','mcq','A pregnant woman at 28 weeks is Rh-negative with no antibodies detected. What is the most appropriate management?','["A. No action needed until delivery","B. Administer anti-D immunoglobulin 500 IU IM now","C. Perform amniocentesis to check fetal Rh status","D. Administer Rh-positive blood transfusion"]','B','Routine antenatal anti-D prophylaxis is given to all non-sensitised Rh-negative women at 28 weeks (and 34 weeks in some protocols). This prevents sensitisation from fetomaternal haemorrhage. Anti-D must also be given after any sensitising event (e.g., invasive procedure, APH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','easy','mcq','Which of the following is the MOST reliable method for confirming gestational age in the first trimester?','["A. Maternal serum hCG level","B. Last menstrual period (LMP)","C. Fundal height measurement","D. Crown-rump length (CRL) on ultrasound"]','D','Crown-rump length measured by ultrasound between 8–13 weeks is the most accurate method for dating pregnancy, with an error margin of ±5 days. LMP is unreliable in women with irregular cycles. hCG cannot date pregnancy precisely.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','mcq','At 34 weeks gestation, a fetus is found to have a biophysical profile (BPP) score of 4 out of 10. What is the next most appropriate step?','["A. Urgent delivery","B. Reassurance and routine follow-up","C. Repeat BPP in one week","D. Amnioinfusion"]','A','A BPP score of 4 or less (out of 10) indicates severe fetal compromise and mandates urgent delivery. The BPP assesses fetal breathing, movement, tone, amniotic fluid volume, and non-stress test. Scores of 8-10 are reassuring; 6 is equivocal; ≤4 requires immediate action.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','hard','mcq','A 32-year-old woman at 10 weeks gestation presents with hyperemesis gravidarum requiring hospitalisation. Which electrolyte abnormality is MOST likely?','["A. Hyponatraemia and metabolic acidosis","B. Hypernatraemia and metabolic alkalosis","C. Hyperkalaemia and metabolic acidosis","D. Hypokalaemia and metabolic alkalosis"]','D','Hyperemesis gravidarum causes persistent vomiting leading to loss of hydrochloric acid, resulting in hypochloraemia, hypokalaemia, and metabolic alkalosis. Dehydration leads to concentrated urine. Treatment includes IV fluids, antiemetics, and thiamine (to prevent Wernicke encephalopathy).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','mcq','A woman presents at 10 weeks for antenatal booking. She has a BMI of 18 kg/m2. What is the recommended total gestational weight gain?','["A. 5–9 kg","B. 11.5–16 kg","C. 7–11.5 kg","D. 12.5–18 kg"]','D','IOM guidelines for gestational weight gain vary by pre-pregnancy BMI: underweight (<18.5) should gain 12.5–18 kg; normal BMI (18.5–24.9) should gain 11.5–16 kg; overweight (25–29.9) should gain 7–11.5 kg; obese (≥30) should gain 5–9 kg.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','hard','mcq','A pregnant woman at 16 weeks is found to have a serum AFP level three times the median for gestational age. Which condition should be suspected?','["A. Edward syndrome (trisomy 18)","B. Down syndrome (trisomy 21)","C. Open neural tube defect","D. Gestational trophoblastic disease"]','C','Elevated maternal serum AFP (>2.5 MoM) is associated with open neural tube defects (spina bifida, anencephaly), abdominal wall defects, and fetal demise. Down syndrome and trisomy 18 are associated with LOW AFP. Gestational trophoblastic disease causes markedly elevated hCG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','mcq','Which of the following fetal surveillance methods uses Doppler to assess placental blood flow resistance?','["A. Umbilical artery Doppler velocimetry","B. Non-stress test","C. Biophysical profile","D. Contraction stress test"]','A','Umbilical artery Doppler velocimetry measures systolic/diastolic (S/D) ratio, pulsatility index, and resistance index. Absent or reversed end-diastolic flow indicates severe placental insufficiency and is associated with fetal growth restriction and perinatal mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','easy','mcq','Which combination of findings defines pre-eclampsia?','["A. Proteinuria + oedema in the third trimester","B. Hypertension ≥160/110 mmHg at any gestation + headache","C. Hypertension ≥140/90 mmHg after 20 weeks + proteinuria ≥300 mg/24h","D. Hypertension ≥130/80 mmHg before 20 weeks + renal impairment"]','C','Pre-eclampsia is defined as new-onset hypertension (BP ≥140/90 mmHg on two readings ≥4 hours apart) after 20 weeks gestation, with proteinuria ≥300 mg/24h (or protein:creatinine ratio ≥30 mg/mmol). In the absence of proteinuria, severe features (thrombocytopenia, renal impairment, impaired liver function, pulmonary oedema, new-onset headache) can establish the diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','mcq','According to the Ghana Standard Treatment Guidelines, what is the first-line treatment for eclamptic seizures?','["A. Diazepam 10 mg IV bolus","B. Phenytoin 18 mg/kg IV loading dose","C. Phenobarbitone 200 mg IM","D. Magnesium sulphate 4 g IV over 5–10 minutes then 1 g/hour infusion"]','D','The Ghana STG recommends magnesium sulphate (MgSO4) as first-line for eclampsia: loading dose of 4 g IV over 5–10 minutes, followed by maintenance infusion of 1–2 g/hour for at least 24 hours after the last seizure. MgSO4 is superior to diazepam and phenytoin in preventing recurrent seizures and reducing maternal mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','mcq','A woman receiving magnesium sulphate infusion develops absent deep tendon reflexes and a respiratory rate of 10 breaths/minute. What is the immediate management?','["A. Administer naloxone 0.4 mg IV","B. Increase the infusion rate","C. Stop MgSO4 infusion and give calcium gluconate 10 mL of 10% solution IV","D. Intubate and ventilate immediately"]','C','Magnesium toxicity presents with loss of deep tendon reflexes (earliest sign), respiratory depression, and cardiac arrest. Management: stop MgSO4 immediately and administer calcium gluconate 1 g (10 mL of 10% solution) IV over 3 minutes as an antidote. Naloxone reverses opioid toxicity, not magnesium.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','mcq','Which antihypertensive is CONTRAINDICATED in pregnancy for treating severe hypertension?','["A. Labetalol","B. Hydralazine","C. ACE inhibitors","D. Nifedipine"]','C','ACE inhibitors (e.g., enalapril, lisinopril) and ARBs are absolutely contraindicated in pregnancy due to fetotoxicity: they cause oligohydramnios, renal tubular dysgenesis, skull ossification defects, and fetal/neonatal death. First-line agents for acute severe hypertension in pregnancy include IV labetalol, IV hydralazine, and oral/sublingual nifedipine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','hard','mcq','A 29-year-old primigravida at 32 weeks presents with BP 168/112 mmHg, right upper quadrant pain, and platelets of 78 × 10⁹/L. AST is 280 U/L and LDH is elevated. What syndrome does she have?','["A. HELLP syndrome","B. Acute fatty liver of pregnancy","C. TTP-HUS","D. Cholestasis of pregnancy"]','A','HELLP syndrome (Haemolysis, Elevated Liver enzymes, Low Platelets) is a severe variant of pre-eclampsia. Diagnostic criteria: microangiopathic haemolytic anaemia, AST/ALT >70 U/L, platelets <100 × 10⁹/L. It carries risk of hepatic rupture, placental abruption, DIC, and maternal death. Delivery is definitive treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','easy','mcq','At what gestational age should a woman with severe pre-eclampsia that cannot be controlled be delivered?','["A. Immediate delivery regardless of gestational age","B. 34 weeks or beyond","C. Only after 37 weeks","D. 28 weeks if uncontrolled"]','A','Eclampsia or uncontrolled severe pre-eclampsia is an indication for immediate delivery regardless of gestational age, after stabilising the mother with antihypertensives and MgSO4. For controlled severe pre-eclampsia, the approach balances fetal maturity and maternal risk; delivery at 34 weeks is generally recommended.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','mcq','Which intervention reduces the risk of pre-eclampsia in high-risk women when started before 16 weeks gestation?','["A. Calcium supplementation 500 mg/day","B. Low-dose aspirin 75–150 mg/day","C. Magnesium supplementation","D. Vitamin C and E supplementation"]','B','Low-dose aspirin (75–150 mg/day) started before 16 weeks significantly reduces the risk of pre-eclampsia by ~60% in high-risk women (previous pre-eclampsia, multifetal gestation, chronic hypertension, diabetes, renal disease, or autoimmune disease). NICE and ACOG both recommend this. Vitamins C and E have not been shown to be effective.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','hard','mcq','A woman at 36 weeks develops severe pre-eclampsia. Hydralazine 5 mg IV is given but BP remains 170/115 mmHg after 20 minutes. What should be done next?','["A. Switch to oral methyldopa","B. Wait 60 minutes before repeating","C. Give a further dose of hydralazine 5–10 mg IV","D. Start sodium nitroprusside infusion"]','C','For acute severe hypertension in pregnancy with hydralazine, if BP remains ≥160/110 mmHg 20 minutes after the initial dose, repeat 5–10 mg IV. Maximum cumulative dose is 20 mg. Sodium nitroprusside is a last resort due to fetal cyanide toxicity risk. Oral methyldopa acts too slowly for acute control.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','hard','mcq','Which laboratory finding is MOST useful in distinguishing pre-eclampsia from chronic hypertension in pregnancy?','["A. Elevated uric acid","B. New-onset proteinuria or worsening proteinuria","C. Elevated haematocrit","D. Low platelet count"]','B','The key distinguishing feature is new-onset proteinuria (or worsening proteinuria in women with pre-existing proteinuria). Chronic hypertension alone does not cause proteinuria unless complicated by pre-eclampsia (superimposed pre-eclampsia). Uric acid elevation, thrombocytopenia, and haemoconcentration can occur in both conditions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','mcq','Which symptom in a woman with pre-eclampsia at 34 weeks should prompt immediate hospitalisation and delivery planning?','["A. Mild ankle swelling","B. Nausea and vomiting","C. Braxton Hicks contractions","D. Epigastric pain and blurred vision"]','D','Epigastric or right upper quadrant pain (hepatic capsule stretching/hepatic haemorrhage), headache, blurred vision, and scotomata are warning symptoms of imminent eclampsia or hepatic rupture. These represent severe features of pre-eclampsia requiring urgent assessment and likely delivery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','easy','mcq','What is the MOST common cause of primary postpartum haemorrhage (PPH)?','["A. Genital tract trauma","B. Retained placenta","C. Uterine atony","D. Coagulopathy"]','C','Uterine atony accounts for 70–80% of primary PPH cases. Primary PPH is defined as blood loss ≥500 mL within 24 hours of delivery (≥1000 mL after caesarean). The "4 Ts" mnemonic covers causes: Tone (atony), Tissue (retained products), Trauma (lacerations), Thrombin (coagulopathy).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','mcq','A woman develops PPH due to uterine atony after vaginal delivery. Oxytocin infusion and uterine massage have failed. What is the next pharmacological agent to use?','["A. Ergometrine 0.5 mg IV","B. Misoprostol 800 mcg sublingual","C. Tranexamic acid 1 g IV","D. Carboprost 250 mcg IM"]','A','After failed oxytocin, ergometrine 0.5 mg IV (or IM if IV access unavailable) is the next step. It causes sustained uterine contraction. It is contraindicated in hypertension. Carboprost (15-methyl PGF2α) is used if ergometrine fails. Tranexamic acid addresses fibrinolysis and should be given early in all PPH cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','hard','mcq','A surgeon performs a B-Lynch compression suture for intractable uterine atony after caesarean section. Which anatomical structure does this suture compress?','["A. The ovarian ligaments","B. Bilateral uterine arteries","C. The internal os only","D. The uterine fundus and lower uterine segment simultaneously"]','D','The B-Lynch suture is a brace suture that compresses the anterior and posterior walls of the uterus simultaneously — it passes over the fundus and through the lower uterine segment, achieving haemostasis by mechanical compression. It preserves the uterus and fertility.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','mcq','During delivery of a macrosomic baby, the fetal head delivers but further expulsion stops despite maternal pushing. What is the FIRST manoeuvre to attempt?','["A. McRoberts manoeuvre","B. Fundal pressure","C. Zavanelli manoeuvre","D. Internal podalic version"]','A','Shoulder dystocia management begins with McRoberts manoeuvre: hyperflexion of the maternal thighs onto the abdomen, which flattens the lumbar lordosis and increases the relative AP diameter of the pelvis. This combined with suprapubic pressure resolves ~50% of cases. Fundal pressure worsens impaction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','mcq','A woman in active labour has a sudden cord prolapse confirmed on vaginal examination. The fetal heart rate is 90 bpm. What is the immediate action?','["A. Administer oxytocin to speed delivery","B. Place the woman in knee-chest or Trendelenburg position and manually elevate the presenting part","C. Attempt vaginal delivery immediately","D. Perform external cephalic version"]','B','Cord prolapse is an obstetric emergency. The umbilical cord must be immediately relieved of pressure: the clinician manually elevates the presenting part per vaginam while the woman is placed in knee-chest or Trendelenburg position to use gravity. Emergency caesarean section is then performed. The cord should be kept warm and moist but not replaced.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','hard','mcq','A multigravida at 39 weeks in active labour suddenly develops severe abdominal pain, maternal tachycardia, and the fetal presenting part can no longer be palpated abdominally. The fetal heart is absent. What is the most likely diagnosis?','["A. Placental abruption","B. Severe pre-eclampsia","C. Amniotic fluid embolism","D. Uterine rupture"]','D','Uterine rupture presents with sudden severe abdominal pain, cessation of contractions, loss of fetal station (presenting part retreats from pelvis), maternal shock, and fetal distress or death. Risk factors include previous caesarean scar, grand multiparity, obstructed labour, and oxytocin use. Immediate laparotomy is required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','easy','mcq','What is the recommended oxytocin dose for active management of the third stage of labour to prevent PPH?','["A. Oxytocin 10 IU IM after delivery of the baby","B. Oxytocin 5 IU IM after delivery of the baby","C. Oxytocin 20 IU IV bolus immediately","D. Oxytocin 5 IU IV bolus followed by 40 IU infusion"]','A','Active management of the third stage (AMTSL) includes: oxytocin 10 IU IM within one minute of delivery of the baby (after excluding a second twin), controlled cord traction, and uterine massage after placental delivery. This reduces PPH risk by 60%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','mcq','Tranexamic acid is administered in PPH. What is its mechanism of action?','["A. Replenishes clotting factors","B. Stimulates uterine contraction","C. Inhibits fibrinolysis by blocking plasminogen activation","D. Causes vasoconstriction of uterine arteries"]','C','Tranexamic acid is an antifibrinolytic agent that competitively inhibits the binding of plasminogen to fibrin, preventing clot degradation. In the WOMAN trial, it reduced PPH mortality by 19% when given within 3 hours of delivery. Dose: 1 g IV over 10 minutes, repeated after 30 minutes if bleeding continues.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','hard','mcq','An internal iliac (hypogastric) artery ligation is performed for intractable PPH. What is the primary haemostatic mechanism?','["A. Reduction in pulse pressure to uterine arteries, promoting thrombosis","B. Complete cessation of blood flow to the uterus","C. Reversal of uterine atony by neurogenic stimulation","D. Ligation of the direct uterine blood supply"]','A','Internal iliac artery ligation reduces pulse pressure (not total blood flow, as collateral circulation develops) in the pelvic vasculature by ~85%. This converts the pelvic arterial circulation into a venous-like system with low pressure, allowing thrombosis and haemostasis. It does not completely devascularise the uterus.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','mcq','Which of the following is an indication for emergency peripartum hysterectomy?','["A. Placenta accreta with failed conservative management","B. Uterine atony responding to bimanual compression","C. Cervical laceration with active bleeding","D. Retained placental fragments"]','A','Emergency peripartum hysterectomy is indicated for placenta accreta spectrum (accreta, increta, percreta) when conservative measures fail, uterine rupture unrepairable, or uterine atony refractory to all medical and surgical measures. Cervical lacerations and retained placental fragments are managed with suture and manual removal, respectively.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','easy','mcq','What is the gestational age range that defines preterm birth?','["A. Less than 28 weeks","B. 24 to 36 weeks","C. Between 28 and 34 weeks","D. Before 37 completed weeks of gestation"]','D','Preterm birth is defined as birth before 37 completed weeks of gestation (i.e., before 37+0). Subcategories: extremely preterm (<28 weeks), very preterm (28–31+6 weeks), moderate to late preterm (32–36+6 weeks). It is the leading cause of neonatal mortality worldwide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','mcq','A woman at 29 weeks gestation presents with premature preterm rupture of membranes (PPROM). What is the priority intervention to improve neonatal outcome?','["A. Antenatal corticosteroids (betamethasone 12 mg IM, two doses 24 hours apart)","B. Immediate induction of labour","C. Emergency caesarean section","D. Oral nifedipine tocolysis for 2 weeks"]','A','Antenatal corticosteroids (betamethasone 12 mg IM in two doses 24 hours apart, or dexamethasone 6 mg IM in four doses 12 hours apart) given between 24–34 weeks reduce neonatal RDS, IVH, NEC, and mortality. This is the single most important intervention. Tocolysis may be given briefly to allow steroid effect but not for prolonged periods in PPROM due to infection risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','mcq','Which antibiotic regimen is recommended for GBS prophylaxis in a woman in preterm labour who is GBS-positive or of unknown status?','["A. Amoxicillin 500 mg orally","B. Clindamycin 600 mg IV every 8 hours for all women","C. Cephalexin 500 mg orally every 6 hours","D. Penicillin G 5 million units IV then 2.5 million units IV every 4 hours"]','D','CDC guidelines recommend penicillin G (IV) as first-line for GBS intrapartum prophylaxis: 5 million units loading dose then 2.5 million units every 4 hours until delivery. Ampicillin 2 g then 1 g IV every 4 hours is an alternative. Clindamycin or vancomycin is used for penicillin-allergic women with susceptibility testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','hard','mcq','Which tocolytic agent is CONTRAINDICATED in a woman at 32 weeks gestation with preterm labour who has a history of asthma?','["A. Nifedipine","B. Indomethacin","C. Salbutamol (terbutaline)","D. Atosiban"]','C','Beta-2 agonists (salbutamol, terbutaline, ritodrine) are contraindicated in women with poorly controlled asthma due to risk of maternal tachycardia and pulmonary oedema, and while they might seem beneficial for asthma, the haemodynamic effects are dangerous in obstetric context. The MAIN concerns are pulmonary oedema and cardiac arrhythmias. Nifedipine is preferred for tocolysis as it has fewer systemic side effects.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','mcq','Which bedside test is MOST useful in confirming rupture of membranes when clinical findings are equivocal?','["A. Placental alpha-microglobulin-1 (PAMG-1) test (AmniSure)","B. pH testing of vaginal discharge","C. Amniocentesis","D. Fern test on vaginal swab"]','A','PAMG-1 (AmniSure) has sensitivity >98% and specificity >99% for PPROM. It detects a placental protein highly concentrated in amniotic fluid. The fern test (crystallisation of amniotic fluid) and nitrazine pH testing are traditional tests but have higher false-positive rates due to blood, semen, or bacterial vaginosis contamination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','easy','mcq','Magnesium sulphate is administered before 32 weeks in preterm labour. What is the primary purpose in this context?','["A. Tocolysis to stop contractions","B. Neuroprotection to prevent cerebral palsy","C. Seizure prophylaxis for pre-eclampsia","D. Prevention of neonatal group B streptococcal infection"]','B','Antenatal MgSO4 given to women at risk of preterm birth before 32 weeks provides fetal neuroprotection and reduces the risk of cerebral palsy by ~32%. This is distinct from its use as tocolysis (where evidence is weak) or anti-seizure prophylaxis in pre-eclampsia. Dose varies by protocol (e.g., 4 g IV loading then 1 g/hour maintenance until delivery or 24 hours).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','hard','mcq','A woman at 34 weeks presents with PPROM and signs of chorioamnionitis (maternal fever >38°C, uterine tenderness, foul-smelling liquor). What is the correct management?','["A. Continue expectant management with oral erythromycin","B. Administer a course of corticosteroids and reassess in 48 hours","C. Immediate delivery and broad-spectrum IV antibiotics","D. Tocolysis with nifedipine to delay delivery"]','C','Chorioamnionitis is an indication for prompt delivery regardless of gestational age, along with broad-spectrum IV antibiotics (e.g., ampicillin + gentamicin ± metronidazole). Expectant management risks maternal sepsis, fetal sepsis, and neonatal death. Tocolysis is absolutely contraindicated in the setting of clinical chorioamnionitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','mcq','A cervical length of less than what measurement on transvaginal ultrasound at 22–24 weeks is associated with significant risk of spontaneous preterm birth?','["A. 35 mm","B. 10 mm","C. 25 mm","D. 40 mm"]','C','A cervical length <25 mm on transvaginal ultrasound at 18–24 weeks is the most important predictor of spontaneous preterm birth. In singleton pregnancies with prior preterm birth and short cervix, vaginal progesterone or cervical cerclage may be offered. In asymptomatic women without prior PTB, vaginal progesterone reduces PTB risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','hard','mcq','Which tocolytic drug acts as an oxytocin receptor antagonist and is licensed for tocolysis in Europe?','["A. Nifedipine","B. Indomethacin","C. Atosiban","D. Magnesium sulphate"]','C','Atosiban (Tractocile) is a competitive oxytocin/vasopressin receptor antagonist licensed for tocolysis in Europe. It reduces myometrial contractions with minimal maternal systemic side effects compared to beta-agonists. It is given as an IV loading dose followed by infusion. It is not currently licensed in the USA.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','mcq','What is the major fetal/neonatal complication of prolonged PPROM at 24 weeks?','["A. Macrosomia","B. Pulmonary hypoplasia","C. Polyhydramnios","D. Neural tube defect"]','B','Prolonged PPROM before 24 weeks (especially if occurring before 20 weeks) leads to oligohydramnios, which impairs fetal lung development via restriction of breathing movements and loss of amniotic fluid lung growth factors. This causes pulmonary hypoplasia — a major cause of neonatal death. Limb deformities and facial compression (Potter sequence) also occur.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','easy','mcq','A 24-year-old woman presents with 6 weeks amenorrhoea, sharp right iliac fossa pain, and vaginal bleeding. Urine hCG is positive. What is the most likely diagnosis?','["A. Threatened miscarriage","B. Ectopic pregnancy","C. Acute appendicitis","D. Ovarian cyst accident"]','B','The classic triad of ectopic pregnancy is amenorrhoea, pelvic pain, and vaginal bleeding in a woman with a positive pregnancy test. The most common site is the ampulla of the fallopian tube (~70%). Risk factors include previous PID, tubal surgery, previous ectopic, IUD use, and assisted reproduction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','mcq','A woman with suspected ectopic pregnancy has serum beta-hCG of 2,500 IU/L and a transvaginal ultrasound showing no intrauterine pregnancy. What should be done?','["A. Admit and repeat hCG in 48 hours; if not rising appropriately, manage as ectopic","B. Administer methotrexate immediately","C. Reassure and repeat pregnancy test in 2 weeks","D. Proceed directly to laparoscopy"]','A','When hCG is above 1,500–2,000 IU/L (discriminatory zone) and no IUP is seen on TVUS, ectopic must be excluded. If clinically stable, serial hCG measurements every 48 hours differentiate: rising >66% = likely IUP; rising <66% or falling slowly = likely ectopic. Laparoscopy is indicated if hCG does not discriminate or patient deteriorates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','mcq','Which criterion MUST be met before treating an ectopic pregnancy with methotrexate?','["A. Ectopic mass <3.5 cm, no fetal cardiac activity, and hCG <5,000 IU/L","B. Haemodynamic instability","C. Serum hCG >5,000 IU/L","D. Confirmed ectopic by diagnostic laparoscopy"]','A','Methotrexate (single-dose 50 mg/m² IM) is suitable for haemodynamically stable women with: ectopic mass ≤3.5 cm (some guidelines 3.5–4 cm), no fetal cardiac activity, hCG <5,000 IU/L (optimal <1,500 IU/L), and no contraindications (liver/renal disease, immunosuppression, thrombocytopenia). Success rate ~85–90% when criteria are met.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','hard','mcq','A woman treated with methotrexate for ectopic pregnancy is seen on day 4 with worsening abdominal pain but haemodynamically stable. hCG has risen compared to pre-treatment level. What does this indicate?','["A. Expected response — the pain and hCG rise on days 3–7 is a normal reaction","B. Heterotopic pregnancy","C. Allergic reaction to methotrexate","D. Methotrexate failure — urgent surgery needed"]','A','A transient rise in serum hCG and increased pain/cramping during days 3–7 after methotrexate is an EXPECTED response due to trophoblastic destruction and local inflammation (the "separation pain"). Success is determined by a ≥15% fall in hCG between days 4 and 7. Failure is declared if hCG does not fall ≥15% or if the patient becomes haemodynamically unstable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','mcq','A ruptured ectopic pregnancy with haemoperitoneum and haemodynamic shock is confirmed. What is the definitive management?','["A. IV methotrexate and resuscitation","B. Diagnostic laparoscopy only to confirm diagnosis","C. Emergency laparoscopic or open salpingectomy with resuscitation","D. Transfuse blood and observe for spontaneous resolution"]','C','Ruptured ectopic with haemodynamic instability requires immediate surgical intervention: salpingectomy (removal of the affected tube) via laparoscopy (preferred if feasible) or laparotomy. Simultaneous resuscitation with IV fluids and blood transfusion is essential. Salpingotomy (tube conservation) may be considered if the contralateral tube is absent or damaged and the patient is stable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','easy','mcq','What is the most common site for an ectopic pregnancy?','["A. Ovary","B. Fallopian tube ampulla","C. Cervix","D. Abdominal cavity"]','B','Approximately 95–97% of ectopic pregnancies occur in the fallopian tube. Of these, ~70% are in the ampullary region, ~12% in the isthmus, ~11% in the fimbrial end. Ovarian, cervical, and abdominal ectopics are rare but carry higher mortality. Cornual/interstitial ectopics rupture later (8–12 weeks) and cause massive haemorrhage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','hard','mcq','A woman who had a salpingectomy for a right-sided ectopic pregnancy now wants to conceive. She has a normal left tube. How does the prior salpingectomy affect future fertility compared to salpingotomy?','["A. Salpingectomy results in significantly lower future IVF success rates","B. Salpingectomy increases risk of contralateral ectopic by threefold","C. Salpingotomy always results in higher cumulative pregnancy rates","D. Salpingectomy and salpingotomy have similar intrauterine pregnancy rates but salpingectomy has lower persistent trophoblast risk"]','D','The RCOG and ESGE recommend salpingectomy over salpingotomy when the contralateral tube is healthy, as it avoids persistent trophoblast (which occurs in 5–10% of salpingotomies) and subsequent ectopic in the conserved tube. Cumulative IUP rates are comparable. Salpingotomy may be preferred when the contralateral tube is absent or diseased.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','mcq','Which finding on transvaginal ultrasound is MOST diagnostic of an ectopic pregnancy?','["A. Adnexal mass with no intrauterine pregnancy","B. Endometrial thickening >8 mm","C. Visualisation of an extrauterine gestational sac with a yolk sac or embryo","D. Free fluid in the pouch of Douglas"]','C','The most definitive TVUS finding is an extrauterine gestational sac containing a yolk sac or embryo (with or without cardiac activity). An adnexal ring sign (empty gestational sac adjacent to ovary) is also highly specific. Free fluid alone or endometrial thickening are non-specific. In up to 20%, TVUS is inconclusive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','mcq','A Rh-negative woman undergoes salpingectomy for ruptured ectopic pregnancy. What additional treatment is required?','["A. No additional treatment needed","B. Anti-D is only required after 12 weeks of gestation","C. Anti-D immunoglobulin 250 IU IM","D. Rhesus immunisation after 4 weeks"]','C','All Rh-negative women with ectopic pregnancy — regardless of gestational age or whether surgical or medical management is used — should receive anti-D immunoglobulin (250 IU IM if <20 weeks). This prevents Rh sensitisation from fetomaternal haemorrhage which could affect future pregnancies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','hard','mcq','A woman with an IUD in situ presents with a positive pregnancy test. What type of ectopic is she at increased risk of compared to the general pregnant population?','["A. Heterotopic pregnancy","B. Cervical ectopic","C. Interstitial ectopic","D. Abdominal ectopic"]','B','IUD use does not increase the absolute risk of ectopic pregnancy but, if pregnancy occurs with an IUD in situ, the relative proportion that are ectopic is higher because IUDs are more effective at preventing intrauterine than ectopic implantation. Cervical ectopics are rare but IUDs are a recognised risk factor. The overall most common ectopic remains tubal.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','easy','mcq','When is the oral glucose tolerance test (OGTT) for gestational diabetes mellitus (GDM) screening recommended?','["A. At the booking visit (first trimester)","B. At 24–28 weeks gestation","C. After 32 weeks gestation","D. At any point when macrosomia is detected"]','B','The standard screening time for GDM using 75 g OGTT is 24–28 weeks gestation in at-risk women (BMI >30, previous GDM, macrosomic baby, family history of T2DM, ethnic minority). Earlier testing at 16 weeks is done if high risk to detect pre-existing undiagnosed T2DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','mcq','Using WHO 2013 criteria, which OGTT result diagnoses gestational diabetes mellitus?','["A. Random glucose ≥11.1 mmol/L with symptoms","B. Fasting plasma glucose ≥7.0 mmol/L","C. 2-hour post-load glucose ≥11.1 mmol/L","D. Fasting plasma glucose ≥5.1 mmol/L or 1-hour ≥10.0 mmol/L or 2-hour ≥8.5 mmol/L"]','D','WHO 2013 (IADPSG) criteria for GDM: fasting ≥5.1 mmol/L, or 1-hour ≥10.0 mmol/L, or 2-hour ≥8.5 mmol/L on 75 g OGTT. Fasting ≥7.0 mmol/L or 2-hour ≥11.1 mmol/L diagnoses overt diabetes in pregnancy, not GDM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','mcq','What are the recommended blood glucose targets for women with GDM on self-monitoring?','["A. Fasting <5.0 mmol/L and 2-hour post-meal <7.0 mmol/L","B. HbA1c <6.5% only","C. Fasting <5.3 mmol/L and 1-hour post-meal <7.8 mmol/L","D. Fasting <6.0 mmol/L and 2-hour post-meal <8.0 mmol/L"]','C','NICE recommends: fasting glucose <5.3 mmol/L, 1-hour postprandial <7.8 mmol/L, 2-hour postprandial <6.4 mmol/L. Tight glucose control reduces risks of macrosomia, shoulder dystocia, neonatal hypoglycaemia, and caesarean section. Diet and exercise are first-line; metformin or insulin if targets not met within 1–2 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','mcq','A woman with GDM has fasting glucose of 6.8 mmol/L despite 2 weeks of dietary modification. What is the next step?','["A. Continue dietary management for another month","B. Add metformin or insulin","C. Induce labour at 37 weeks without medication","D. Start sulphonylurea (glibenclamide)"]','B','When glucose targets are not achieved with dietary and lifestyle modifications within 1–2 weeks, pharmacological therapy is indicated. Metformin (if not contraindicated) or insulin (gold standard) are used. Insulin is preferred if fasting glucose is markedly elevated (>7 mmol/L), or in early pregnancy. Glibenclamide is used in some settings but NICE does not recommend it as first-line.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','hard','mcq','A woman with GDM delivers a 4.6 kg baby at 38 weeks. The neonate develops jitteriness and a blood glucose of 1.8 mmol/L at 2 hours of life. What is the mechanism of neonatal hypoglycaemia?','["A. Neonatal hyperinsulinism due to chronic fetal hyperglycaemia in utero","B. Placental insufficiency causing reduced glycogen stores","C. Neonatal adrenal insufficiency","D. Maternal insulin crossing the placenta after delivery"]','A','Chronic maternal hyperglycaemia causes fetal hyperglycaemia, which stimulates fetal pancreatic beta-cell hyperplasia and excess insulin secretion (hyperinsulinism). At delivery, the glucose supply from the mother ceases abruptly while neonatal hyperinsulinism persists, causing hypoglycaemia. This is the Pedersen hypothesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','easy','mcq','What long-term risk does a woman with a history of GDM face after delivery?','["A. 50% risk of developing type 2 diabetes within 5–10 years","B. Permanent insulin dependence","C. 10% risk of developing type 1 diabetes within 1 year","D. She has no increased risk of diabetes"]','A','Women with GDM have a 35–60% lifetime risk of developing T2DM, with the highest risk in the first 5 years postpartum. They should have a 75 g OGTT at 6–13 weeks postpartum and annual fasting glucose or HbA1c thereafter. Lifestyle modification can reduce progression to T2DM by 50–60%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','hard','mcq','A woman with pre-existing type 1 diabetes at 8 weeks gestation has HbA1c of 9.2%. What is the MAIN fetal risk during organogenesis from poor glycaemic control?','["A. Macrosomia","B. Neonatal hypoglycaemia","C. Preterm birth","D. Major congenital anomalies"]','D','During the first 8 weeks (organogenesis), poor glycaemic control (high HbA1c) increases the risk of major congenital anomalies — most commonly cardiac defects (ventricular septal defect, transposition), neural tube defects, and caudal regression syndrome. This is the key distinction from GDM (which develops after organogenesis). Pre-conception HbA1c optimisation to <6.5% is critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','mcq','At what gestational age is elective delivery recommended for well-controlled GDM on diet alone with no complications?','["A. 40–41 weeks","B. 38–39 weeks","C. 37 weeks","D. 42 weeks"]','A','For well-controlled GDM managed with diet alone, with appropriate fetal growth and no other complications, delivery is recommended at 40–41 weeks (not earlier than 40 weeks). For GDM requiring insulin or with macrosomia/poor control, delivery at 38–39 weeks is recommended to reduce the risk of stillbirth and shoulder dystocia.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','mcq','Which obstetric complication is MOST directly associated with untreated macrosomia in GDM?','["A. Placenta praevia","B. Preterm labour","C. Placental abruption","D. Shoulder dystocia"]','D','Macrosomia (estimated fetal weight >4 kg or >90th centile) is the hallmark complication of GDM and is the primary risk factor for shoulder dystocia — where the anterior fetal shoulder becomes impacted behind the maternal pubic symphysis after head delivery. This is an obstetric emergency that can cause brachial plexus injury and perinatal asphyxia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','hard','mcq','Metformin is used as an alternative to insulin in GDM. What is the key pharmacological consideration regarding metformin in pregnancy?','["A. Metformin does not cross the placenta","B. Metformin crosses the placenta and fetal metformin levels approach maternal levels","C. Metformin causes fetal hyperinsulinism","D. Metformin is teratogenic in the first trimester"]','B','Metformin freely crosses the placenta and fetal blood levels approach maternal concentrations. Long-term follow-up studies (MiG TOFU) show no adverse effects on offspring at ages 2 and 7–9 years regarding metabolic or developmental outcomes, though some concerns remain about potential epigenetic effects on offspring adiposity. Metformin reduces HbA1c with low hypoglycaemia risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','easy','mcq','What does the PALM-COEIN classification system describe?','["A. Causes of abnormal uterine bleeding in reproductive-age women","B. Assessment of cervical pathology","C. Endometrial cancer grading","D. Staging of uterine fibroids"]','A','PALM-COEIN is the FIGO classification for abnormal uterine bleeding (AUB): Structural causes — Polyp, Adenomyosis, Leiomyoma, Malignancy/Hyperplasia; Non-structural causes — Coagulopathy, Ovulatory dysfunction, Endometrial, Iatrogenic, Not yet classified. Heavy menstrual bleeding (HMB) is defined as >80 mL/cycle or bleeding impairing quality of life.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','mcq','A 38-year-old woman presents with heavy, regular menstrual bleeding (8–9 days). She does not wish to conceive. Uterus is bulky and tender on palpation. Transvaginal ultrasound shows a thickened, heterogeneous myometrium. What is the most likely diagnosis?','["A. Uterine fibroids (submucosal)","B. Endometrial carcinoma","C. Adenomyosis","D. Endometrial polyp"]','C','Adenomyosis is characterised by ectopic endometrial glands within the myometrium, causing dysmenorrhoea, heavy menstrual bleeding, and a tender, uniformly enlarged uterus. TVUS shows heterogeneous myometrium, asymmetrical enlargement, cysts, and linear striations. MRI is the gold standard. Treatment: LNG-IUS, combined OCP, or hysterectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','mcq','A 45-year-old woman with heavy menstrual bleeding is found to have a 5 cm intramural fibroid on ultrasound. She has completed her family. What is the most appropriate definitive surgical treatment?','["A. Hysteroscopic resection","B. Hysterectomy","C. Uterine artery embolisation","D. Myomectomy"]','B','For women with completed family who have failed medical management or have significant symptoms from fibroids, hysterectomy is the only definitive cure. Hysteroscopic resection is for submucosal fibroids; it does not access intramural fibroids adequately. UAE is appropriate for women who wish to avoid surgery but who have predominantly submucosal/intramural fibroids. Myomectomy is appropriate if fertility is desired.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','easy','mcq','What investigation is MOST important to exclude in a postmenopausal woman presenting with vaginal bleeding?','["A. Cervical cancer","B. Ovarian cancer","C. Endometrial cancer","D. Vulval cancer"]','C','Postmenopausal bleeding (PMB) must be considered endometrial cancer until proven otherwise. ~10% of women with PMB have endometrial cancer. Investigations include transvaginal ultrasound (endometrial thickness >4–5 mm is abnormal) and endometrial biopsy (Pipelle sampling or hysteroscopy with directed biopsy).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','mcq','A 25-year-old woman presents with menorrhagia since menarche and frequent nosebleeds. Her mother had similar bleeding problems. Full blood count shows anaemia; clotting screen shows prolonged APTT. What is the most likely underlying cause?','["A. Thrombocytopenia","B. Antiphospholipid syndrome","C. Factor V Leiden mutation","D. Von Willebrand disease"]','D','Von Willebrand disease (VWD) is the most common inherited bleeding disorder and an important cause of menorrhagia from menarche. Features: mucocutaneous bleeding (epistaxis, bruising, menorrhagia), prolonged APTT (in type 2N and 3), low factor VIII, abnormal VWF antigen/activity. Desmopressin (DDAVP) and tranexamic acid are used in treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','hard','mcq','A 30-year-old nulliparous woman with irregular heavy bleeding and signs of androgen excess (acne, hirsutism) is found to have anovulatory cycles. Which AUB-COEIN category applies?','["A. AUB-E (Endometrial)","B. AUB-O (Ovulatory dysfunction)","C. AUB-C (Coagulopathy)","D. AUB-I (Iatrogenic)"]','B','Ovulatory dysfunction (AUB-O) causes irregular, unpredictable, and often heavy bleeding due to anovulation. Causes include PCOS, thyroid disease, hyperprolactinaemia, and perimenopause. In PCOS, chronic oestrogen stimulation without progesterone withdrawal causes endometrial hyperplasia and heavy breakthrough bleeding. Treatment targets the underlying cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','mcq','What is the first-line medical treatment for heavy menstrual bleeding (HMB) in women NOT wishing to conceive?','["A. Levonorgestrel-releasing intrauterine system (LNG-IUS, Mirena)","B. Tranexamic acid 1 g TDS during menses","C. Oral norethisterone 5 mg TDS","D. Combined oral contraceptive pill"]','A','The LNG-IUS (Mirena, 52 mg) is the first-line treatment for HMB in women not wishing to conceive. It reduces menstrual blood loss by 80–90% via local progestogenic endometrial atrophy. It is also highly effective for adenomyosis. Tranexamic acid and NSAIDs are effective but require use each cycle.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','hard','mcq','A woman with heavy menstrual bleeding has a pipelle endometrial biopsy showing complex atypical endometrial hyperplasia. She is 42 and has completed her family. What is the recommended management?','["A. Oral progestins for 6 months and repeat biopsy","B. Hysterectomy","C. LNG-IUS for 12 months","D. GnRH analogues for 3 months"]','B','Complex atypical endometrial hyperplasia (now termed endometrial intraepithelial neoplasia) has a ~30% risk of concurrent endometrial carcinoma and a high risk of progression to cancer. In women who have completed their family, total hysterectomy (with bilateral salpingo-oophorectomy) is the recommended treatment. Conservative management with progestins is only for younger women wishing to preserve fertility under close surveillance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','mcq','A 19-year-old presents with intermenstrual bleeding and post-coital bleeding. Cervical ectropion is seen. What additional investigation is mandatory?','["A. Cervical smear and STI screen (chlamydia/gonorrhoea)","B. Hysteroscopy","C. Pelvic MRI","D. Endometrial biopsy"]','A','Post-coital bleeding and intermenstrual bleeding in a young woman requires cervical smear (if due) and STI screening especially for Chlamydia trachomatis, which causes cervicitis and is the most common bacterial STI in this age group. Cervical ectropion is a common benign finding but must not mask underlying infection or, in older women, cervical cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','hard','mcq','Uterine artery embolisation (UAE) is offered to a 40-year-old with symptomatic uterine fibroids. Which fibroid type responds BEST to UAE?','["A. Subserosal pedunculated fibroids","B. Intramural fibroids with submucosal component","C. Submucosal fibroids","D. Calcified fibroids"]','B','UAE works best for intramural fibroids, especially those with a submucosal component, as embolisation infarcts the fibroid. Subserosal pedunculated fibroids are a RELATIVE contraindication to UAE (risk of peduncle ischaemia and peritonitis). Calcified fibroids have poor blood supply and respond poorly. Success rate is 85–90% for symptom relief.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','easy','mcq','Which clinical triad is MOST characteristic of pelvic inflammatory disease (PID)?','["A. Lower abdominal pain, cervical motion tenderness, and adnexal tenderness","B. Menorrhagia, dyspareunia, and infertility","C. Dysuria, frequency, and suprapubic pain","D. Fever, vomiting, and right iliac fossa pain"]','A','The clinical diagnosis of PID is based on minimum criteria (LOWER abdominal pain + cervical motion tenderness + adnexal tenderness) with or without fever, elevated WBC/CRP, positive cervical discharge, or evidence of endometritis on biopsy. PID is caused by ascending infection from the lower genital tract, most commonly Chlamydia trachomatis and Neisseria gonorrhoeae.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','mcq','According to the Ghana Standard Treatment Guidelines, what is the first-line outpatient antibiotic regimen for uncomplicated PID?','["A. Doxycycline 100 mg BD for 14 days only","B. Azithromycin 1 g single dose","C. Amoxicillin 500 mg TDS for 7 days","D. Cefixime 400 mg stat + doxycycline 100 mg BD + metronidazole 400 mg TDS for 14 days"]','D','Ghana STG syndromic management of PID (outpatient): Cefixime 400 mg orally single dose (or ceftriaxone 250 mg IM) PLUS doxycycline 100 mg BD for 14 days PLUS metronidazole 400–500 mg BD/TDS for 14 days. This covers Chlamydia, gonorrhoea, and anaerobes (Bacteroides, anaerobic streptococci). Azithromycin single dose does not cover gonorrhoea adequately.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','mcq','A woman with PID develops a pelvic abscess (tubo-ovarian abscess, TOA) confirmed on ultrasound. Initial IV antibiotics have been given for 48 hours without improvement. What is the next step?','["A. Continue same antibiotics for another week","B. Surgical drainage (laparoscopic or image-guided)","C. Add oral metronidazole only","D. Immediate hysterectomy"]','B','TOA that fails to respond to 48–72 hours of IV antibiotics requires drainage — either laparoscopically or via image-guided (ultrasound or CT) percutaneous drainage. Hysterectomy is reserved for ruptured TOA with sepsis or failure of drainage. Ruptured TOA is a surgical emergency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','mcq','What is the treatment for primary syphilis according to the Ghana STG?','["A. Doxycycline 100 mg BD for 14 days","B. Ceftriaxone 1 g IM for 10 days","C. Benzathine penicillin G 2.4 million units IM single dose","D. Azithromycin 2 g single dose"]','C','Ghana STG and WHO guidelines recommend benzathine penicillin G 2.4 million units IM as a single dose for primary, secondary, and early latent syphilis. Late latent or tertiary syphilis requires three weekly doses. Doxycycline 100 mg BD for 14 days is an alternative for penicillin-allergic patients. Azithromycin 2 g is an alternative in some settings but resistance is increasing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','easy','mcq','A patient presents with a painless indurated genital ulcer. Darkfield microscopy shows motile spirochaetes. What is the diagnosis?','["A. Chancroid (Haemophilus ducreyi)","B. Lymphogranuloma venereum","C. Herpes simplex virus infection","D. Primary syphilis (Treponema pallidum)"]','D','The painless, indurated, clean-based chancre with inguinal lymphadenopathy is pathognomonic of primary syphilis. Treponema pallidum is identified by darkfield microscopy. Chancroid causes painful, purulent ulcers with tender, fluctuant inguinal nodes. HSV causes multiple, painful, vesicular ulcers. VDRL/RPR is used for serological screening.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','hard','mcq','A woman with PID is found to have a Fitz-Hugh-Curtis syndrome. What additional clinical finding would be expected?','["A. Ascending cholangitis","B. Fever and jaundice from hepatitis","C. Elevated amylase from peritoneal involvement","D. Right upper quadrant pain due to perihepatitis"]','D','Fitz-Hugh-Curtis syndrome (perihepatitis) is a complication of PID (usually chlamydial or gonococcal) characterised by inflammation of the hepatic capsule and peritoneum, causing right upper quadrant pain, a friction rub over the liver, and violin-string adhesions seen at laparoscopy. Liver function tests may be mildly elevated. It is often mistaken for cholecystitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','mcq','A 22-year-old man presents with urethral discharge and dysuria. Gram stain of the discharge shows Gram-negative intracellular diplococci. What is the treatment according to WHO/Ghana STG guidelines?','["A. Ceftriaxone 500 mg IM single dose plus azithromycin 1 g orally single dose","B. Doxycycline 100 mg BD for 7 days alone","C. Ciprofloxacin 500 mg single dose","D. Ampicillin 3 g single dose"]','A','WHO and Ghana STG recommend dual therapy for gonorrhoea: ceftriaxone 500 mg IM (or 250 mg IM in some guidelines) PLUS azithromycin 1 g orally as a single dose to cover concurrent chlamydia and reduce development of ceftriaxone resistance. Ciprofloxacin resistance is widespread. Dual therapy is now standard globally.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','hard','mcq','A 28-year-old woman with PID develops a right-sided tender adnexal mass. At laparoscopy, a TOA and peritubal adhesions are found. What long-term sequela is she at GREATEST risk of?','["A. Endometrial cancer","B. Tubal factor infertility and ectopic pregnancy","C. Ovarian failure","D. Chronic cervicitis"]','B','PID causes tubal damage through inflammation and adhesion formation. A single episode of PID causes tubal factor infertility in ~12%, rising to ~23% after two episodes and ~54% after three or more episodes. The risk of ectopic pregnancy is increased 6–10-fold due to tubal scarring. TOA further increases the risk. Early treatment minimises sequelae.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','mcq','Which STI is the most common cause of genital ulcers in sub-Saharan Africa and is associated with painful inguinal lymphadenopathy (buboes)?','["A. Syphilis","B. Herpes simplex virus type 2","C. Chancroid (Haemophilus ducreyi)","D. Lymphogranuloma venereum (Chlamydia trachomatis L1–L3)"]','C','Chancroid caused by Haemophilus ducreyi is endemic in sub-Saharan Africa and causes painful, soft, irregular, necrotic genital ulcers with painful, tender inguinal lymphadenopathy (buboes) that may become fluctuant. Treatment: azithromycin 1 g single dose or ceftriaxone 250 mg IM single dose. HSV is most common globally; chancroid is most common cause of ulcers in Africa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','easy','mcq','Which investigation is most sensitive for detecting Chlamydia trachomatis in women?','["A. Cervical culture","B. Enzyme immunoassay (EIA)","C. Gram stain of cervical discharge","D. Nucleic acid amplification test (NAAT) on endocervical or vaginal swab"]','D','NAATs (PCR-based) are the gold standard for detecting Chlamydia trachomatis with sensitivity >90% and specificity >99%. They can be performed on endocervical swabs, vaginal swabs, or urine samples. Culture is less sensitive (~60–80%) and requires special transport conditions. Gram stain is not useful for chlamydia (intracellular, not Gram-stainable as bacteria).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','mcq','A 35-year-old woman has a cervical smear showing high-grade squamous intraepithelial lesion (HSIL / CIN3). What is the recommended treatment?','["A. Repeat smear in 6 months","B. Hysterectomy","C. Colposcopy-guided biopsy and LLETZ (large loop excision of the transformation zone)","D. Cryotherapy only"]','C','CIN3/HSIL is managed with colposcopic assessment and LLETZ (loop electrosurgical excision procedure), which excises the transformation zone containing the abnormal epithelium. LLETZ is both diagnostic (histological) and therapeutic. Hysterectomy is not first-line for CIN3. Cold coagulation or laser can be alternatives but are less commonly used.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','mcq','A 52-year-old woman is diagnosed with FIGO Stage IB2 cervical cancer (tumour 5 cm, confined to cervix). What is the standard treatment?','["A. Concurrent chemoradiotherapy (cisplatin-based)","B. Simple hysterectomy","C. Radical trachelectomy","D. Neoadjuvant chemotherapy followed by radical hysterectomy only"]','A','For locally advanced cervical cancer (Stage IB2 and above), concurrent chemoradiotherapy (cisplatin 40 mg/m² weekly with external beam radiotherapy plus brachytherapy) is the standard treatment. This is superior to radiotherapy alone. Radical hysterectomy (Wertheim) is appropriate for Stage IA2 and IB1 (<4 cm). Trachelectomy is for Stage IA2–IB1 in women desiring fertility.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','easy','mcq','Which oncogenic HPV types are responsible for the majority of cervical cancers?','["A. HPV 6 and 11","B. HPV 33 and 52","C. HPV 31 and 45","D. HPV 16 and 18"]','D','HPV types 16 and 18 are responsible for ~70% of cervical cancers worldwide. HPV 16 predominantly causes squamous cell carcinoma; HPV 18 is more associated with adenocarcinoma. HPV 6 and 11 cause genital warts (condylomata acuminata) — low-risk types. The nonavalent vaccine (Gardasil 9) covers HPV 6, 11, 16, 18, 31, 33, 45, 52, 58.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','mcq','A 63-year-old woman presents with postmenopausal bleeding. Endometrial biopsy shows well-differentiated endometrioid adenocarcinoma. Imaging confirms the tumour is limited to the endometrium. What FIGO stage is this?','["A. Stage IIIA","B. Stage IB","C. Stage II","D. Stage IA"]','D','FIGO 2009 endometrial cancer staging: Stage IA = tumour confined to endometrium or invades less than half the myometrium; Stage IB = invades ≥50% of myometrium; Stage II = cervical stromal invasion; Stage III = extends outside uterus. Stage IA has >95% 5-year survival and is treated with total abdominal hysterectomy + bilateral salpingo-oophorectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','hard','mcq','A 55-year-old woman presents with an abdominal mass, ascites, and elevated CA-125 of 450 U/mL. CT shows a bilateral ovarian mass with omental caking. What is the most likely diagnosis and recommended management?','["A. Endometrial cancer; total hysterectomy","B. Ovarian cancer Stage IIIC; primary debulking surgery followed by platinum-taxane chemotherapy","C. Borderline ovarian tumour; laparoscopic cystectomy","D. Fibroid with degeneration; UAE"]','B','CA-125 elevation, bilateral masses, ascites, and omental deposits are classic for advanced ovarian cancer (FIGO Stage IIIC — intraperitoneal metastases >2 cm or retroperitoneal lymph nodes). Treatment: primary cytoreductive surgery (optimal debulking: residual disease <1 cm) followed by carboplatin-paclitaxel chemotherapy. PARP inhibitors (olaparib) for BRCA1/2-mutated tumours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','hard','mcq','Which hereditary syndrome is associated with increased risk of both ovarian and endometrial cancer?','["A. Lynch syndrome (HNPCC)","B. Li-Fraumeni syndrome","C. BRCA1/2 mutation only","D. Von Hippel-Lindau disease"]','A','Lynch syndrome (HNPCC — hereditary non-polyposis colorectal cancer) is caused by germline mutations in DNA mismatch repair genes (MLH1, MSH2, MSH6, PMS2). It confers a 40–60% lifetime risk of endometrial cancer and 10–12% risk of ovarian cancer (in addition to colorectal, gastric, and other cancers). BRCA1/2 primarily increase ovarian and breast cancer risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','mcq','A 28-year-old woman is diagnosed with cervical cancer Stage IA1 and wants to preserve her fertility. What surgical option is appropriate?','["A. Radical hysterectomy with lymph node dissection","B. Simple hysterectomy","C. Conisation (cone biopsy) with clear margins","D. Chemoradiotherapy"]','C','Stage IA1 cervical cancer (microinvasive, depth ≤3 mm, horizontal spread ≤7 mm) with no lymphovascular space invasion has negligible lymph node metastasis risk. Conisation with clear surgical margins is curative and fertility-sparing. If margins are involved, re-excision or simple trachelectomy may be required. Radical trachelectomy is used for Stage IA2–IB1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','easy','mcq','What is the most common histological type of ovarian cancer?','["A. Mucinous carcinoma","B. Endometrioid carcinoma","C. High-grade serous carcinoma","D. Clear cell carcinoma"]','C','High-grade serous carcinoma (HGSC) is the most common ovarian cancer histotype, accounting for ~70% of all epithelial ovarian cancers. It is strongly associated with BRCA1/2 mutations and often presents at advanced stage (III–IV). It is the most lethal gynaecological cancer. It is thought to arise from the fimbriated end of the fallopian tube.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','hard','mcq','A 45-year-old woman with endometrial cancer is found to have microsatellite instability (MSI-high) on tumour testing. This has implications for which treatment if the cancer is advanced/recurrent?','["A. PARP inhibitor (olaparib)","B. Immune checkpoint inhibitor (pembrolizumab)","C. Bevacizumab (anti-VEGF)","D. HER2-targeted therapy (trastuzumab)"]','B','MSI-high or mismatch repair-deficient (dMMR) endometrial cancers respond to PD-1/PD-L1 immune checkpoint inhibitors. Pembrolizumab (anti-PD-1) has been approved for MSI-high/dMMR tumours regardless of histological type. In advanced/recurrent endometrial cancer, pembrolizumab + lenvatinib is now standard second-line therapy. PARP inhibitors target BRCA1/2 mutations.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','mcq','A woman with vulval cancer has a 2 cm lesion confined to the vulva with no lymph node involvement. What FIGO stage is this?','["A. Stage IV","B. Stage II","C. Stage III","D. Stage I"]','D','FIGO 2009 vulval cancer staging: Stage I = tumour confined to vulva or perineum, no lymph node metastasis; Stage IA ≤2 cm with stromal invasion ≤1 mm; Stage IB >2 cm or stromal invasion >1 mm. Stage II = any size extending to lower urethra, lower vagina, or anus, no lymph nodes. Stage III = inguinofemoral lymph node metastasis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','easy','mcq','A 68-year-old man presents with nocturia, hesitancy, poor urinary stream, and a sensation of incomplete bladder emptying. DRE shows a smoothly enlarged, non-tender prostate. What is the most likely diagnosis?','["A. Prostate cancer","B. Prostatitis","C. Benign prostatic hyperplasia (BPH)","D. Bladder cancer"]','C','BPH is the most common benign condition in men over 50. It causes lower urinary tract symptoms (LUTS) — obstructive (hesitancy, poor stream, incomplete emptying, terminal dribbling) and irritative (frequency, urgency, nocturia). DRE shows a smooth, symmetrically enlarged prostate. PSA may be mildly elevated. Initial assessment: IPSS score, urine dipstick, post-void residual, and renal function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','mcq','A man with BPH and moderate LUTS (IPSS 14) is started on medical therapy. Which drug class is FIRST-LINE for symptom relief?','["A. 5-alpha reductase inhibitors (finasteride)","B. Anticholinergics (solifenacin)","C. Alpha-1 adrenoceptor blockers (tamsulosin)","D. PDE-5 inhibitors (tadalafil)"]','C','Alpha-1 adrenoceptor blockers (tamsulosin, alfuzosin, doxazosin) are first-line for BPH-LUTS symptom relief. They work by relaxing smooth muscle in the bladder neck and prostate, improving urinary flow within days. 5-ARIs (finasteride, dutasteride) reduce prostate volume and are used for large prostates (>40 mL) or in combination with alpha-blockers for long-term management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','mcq','A 72-year-old man with a hard, nodular prostate on DRE has PSA of 22 ng/mL. Transrectal ultrasound-guided biopsy shows Gleason grade group 4 adenocarcinoma. CT chest/abdomen/pelvis shows no metastases. What is the most appropriate treatment?','["A. Active surveillance","B. Orchidectomy alone","C. Watchful waiting only","D. Radical prostatectomy or radical radiotherapy with androgen deprivation therapy"]','D','Gleason grade group 4 (Gleason 4+4=8) is high-risk localised prostate cancer. Treatment options for fit patients include radical prostatectomy (retropubic or laparoscopic) or radical radiotherapy (external beam ± brachytherapy) combined with long-course androgen deprivation therapy (2–3 years). Active surveillance is NOT appropriate for high-risk disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','hard','mcq','A 65-year-old man is on active surveillance for low-risk prostate cancer (Gleason 3+3=6, PSA 5 ng/mL, T1c). His PSA doubles from 5 to 10 ng/mL over 18 months. What should be done?','["A. Continue active surveillance without intervention","B. Repeat PSA in 6 months","C. Reclassify to intermediate risk and offer definitive treatment","D. Start androgen deprivation therapy immediately"]','C','PSA doubling time <3 years (or velocity >2 ng/mL/year) during active surveillance is a trigger for reclassification and re-biopsy. If progression to higher grade/stage is confirmed, definitive treatment (surgery or radiotherapy) is recommended. Active surveillance is only appropriate for low-risk/very low-risk disease with stable PSA kinetics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','mcq','A 70-year-old man develops acute urinary retention and is catheterised. Post-void residual is 650 mL. He has been on tamsulosin for BPH. What surgical procedure is definitive treatment?','["A. Suprapubic catheterisation only","B. Urethral dilation","C. Radical prostatectomy","D. Transurethral resection of the prostate (TURP)"]','D','TURP is the gold standard surgical treatment for BPH causing urinary retention, recurrent UTIs, renal impairment, or failed medical management. It removes the obstructing prostatic tissue endoscopically via the urethra. Complications include TUR syndrome (dilutional hyponatraemia from glycine absorption), bleeding, and retrograde ejaculation (~65–90%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','hard','mcq','A man undergoes TURP and develops confusion, nausea, and bradycardia intraoperatively. Serum sodium is 118 mmol/L. What is the complication?','["A. Pulmonary oedema from fluid overload","B. Haemolysis from blood transfusion","C. Air embolism","D. TUR syndrome (dilutional hyponatraemia from glycine absorption)"]','D','TUR syndrome occurs when hypotonic irrigating fluid (glycine 1.5% or sorbitol) is absorbed into the circulation via open prostatic venous sinuses during TURP. This causes dilutional hyponatraemia, hyperglycaemia (from sorbitol metabolism), and hypo-osmolality leading to cerebral oedema (confusion, seizures), bradycardia, and hyponatraemia. Treatment: stop surgery, restrict fluids, IV hypertonic saline if Na <120 mmol/L.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','easy','mcq','A 58-year-old man has PSA of 8 ng/mL on routine screening. What is the next investigation?','["A. Repeat PSA in 5 years","B. Transrectal ultrasound-guided (TRUS) prostate biopsy","C. MRI of the prostate (mpMRI)","D. CT scan of the abdomen"]','C','Current guidelines (NICE 2019, EAU) recommend multiparametric MRI (mpMRI) of the prostate BEFORE biopsy when PSA is elevated or DRE is suspicious. mpMRI stratifies risk (PI-RADS score 1–5), guides targeted biopsy, and reduces unnecessary biopsies. TRUS biopsy alone has 30–40% false-negative rate for clinically significant cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','mcq','Which medication used for BPH can cause erectile dysfunction and decreased libido as side effects?','["A. Tamsulosin","B. Finasteride","C. Solifenacin","D. Alfuzosin"]','B','5-alpha reductase inhibitors (finasteride, dutasteride) inhibit conversion of testosterone to dihydrotestosterone (DHT), reducing prostate volume by ~25% over 6–12 months. Side effects include erectile dysfunction, decreased libido, ejaculatory disorders, and gynaecomastia in ~5–10%. They also lower PSA by ~50% (important for cancer screening — PSA should be doubled when interpreting results in men on finasteride).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','hard','mcq','A 74-year-old man is diagnosed with metastatic castration-sensitive prostate cancer (mCSPC) with bone metastases. What is the standard of care?','["A. Radical prostatectomy","B. Watchful waiting until symptomatic","C. Radiation to all metastatic sites","D. Androgen deprivation therapy (LHRH agonist) plus docetaxel or abiraterone"]','D','For metastatic castration-sensitive prostate cancer (mCSPC), androgen deprivation therapy (LHRH agonist such as leuprorelin or goserelin) combined with either docetaxel (CHAARTED trial) or abiraterone acetate + prednisolone (LATITUDE trial) or enzalutamide (ARCHES trial) has shown significant overall survival benefit. ADT monotherapy is no longer standard of care for high-volume/high-risk mCSPC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','mcq','What is the mechanism by which LHRH agonists (e.g., leuprorelin) achieve androgen deprivation in prostate cancer?','["A. Direct blockade of androgen receptors in prostate cells","B. Initial LH surge causing testosterone flare, followed by downregulation of LHRH receptors and castrate testosterone levels","C. Inhibition of adrenal androgen synthesis","D. Direct inhibition of 5-alpha reductase"]','B','LHRH agonists (goserelin, leuprorelin) cause an initial LH/FSH surge (testosterone flare) lasting 1–2 weeks, which can worsen symptoms (spinal cord compression, pain). Continuous stimulation then desensitises pituitary LHRH receptors, causing downregulation and suppression of LH/FSH, resulting in castrate testosterone levels (<50 ng/dL) within 3–4 weeks. Anti-androgens (bicalutamide) are co-prescribed during the first 2 weeks to block the flare.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','easy','mcq','How is infertility defined in clinical practice?','["A. Failure to conceive after 12 months of regular unprotected intercourse in women under 35","B. Failure to conceive after 6 months of unprotected intercourse","C. Failure to conceive after 24 months regardless of age","D. Any difficulty conceiving requiring medical attention"]','A','Infertility is defined as failure to conceive after 12 months of regular (2–3 times per week) unprotected sexual intercourse in women under 35 years. For women aged 35 and above, investigation begins after 6 months. Primary infertility = no previous conception; secondary infertility = previous conception. Prevalence is ~15–20% of couples.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','mcq','Which semen analysis parameter is MOST predictive of natural conception?','["A. Total sperm count only","B. Semen pH","C. Sperm volume only","D. Total motile sperm count (TMSC) and morphology (Kruger strict criteria)"]','D','WHO 2021 reference values: sperm concentration ≥16 × 10⁶/mL, total motility ≥42%, progressive motility ≥30%, morphology ≥4% (Kruger strict). Total motile sperm count (TMSC = volume × concentration × motility) is the most clinically useful predictor: TMSC ≥5 million = IUI candidate; TMSC 1–5 million = IVF; TMSC <1 million = ICSI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','mcq','A 30-year-old woman with secondary infertility had a previous episode of PID. Which investigation best assesses tubal patency?','["A. Hysterosalpingography (HSG) or laparoscopy with chromopertubation","B. Transvaginal ultrasound","C. Serum CA-125","D. Endometrial biopsy"]','A','Tubal factor is responsible for ~25–35% of female infertility. Assessment options: HSG (X-ray with contrast — first-line, less invasive), HyCoSy (ultrasound with contrast), or laparoscopy with chromopertubation (gold standard — direct visualisation with blue dye). Laparoscopy also diagnoses and treats endometriosis and adhesions simultaneously.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','mcq','A couple present with infertility. The female partner has a regular 28-day cycle with confirmed ovulation. The male partner has a TMSC of 2 million. What is the most appropriate assisted reproductive option?','["A. IUI (intrauterine insemination)","B. IVF without ICSI","C. ICSI (intracytoplasmic sperm injection)","D. Donor sperm insemination"]','B','TMSC 1–5 million falls into the IVF range. IVF (without ICSI) is appropriate if TMSC is 1–5 million and morphology is reasonable. ICSI is indicated when TMSC <1 million, severe morphology defects, previous failed IVF fertilisation, or azoospermia with surgical sperm retrieval. IUI requires TMSC ≥5 million.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','hard','mcq','A 38-year-old woman has an AMH of 0.4 pmol/L and antral follicle count of 2 on ultrasound. She is about to commence IVF. What does this indicate?','["A. Excellent ovarian reserve; standard stimulation protocol","B. Diminished ovarian reserve; risk of poor response to ovarian stimulation","C. Polycystic ovarian morphology; risk of OHSS","D. Premature ovarian insufficiency; donor eggs not indicated yet"]','B','Anti-Mullerian hormone (AMH) <0.4–1.0 pmol/L and AFC <5–7 indicate diminished ovarian reserve (DOR). This predicts poor response to gonadotrophin stimulation in IVF — fewer oocytes retrieved, lower pregnancy rates. Higher doses of FSH are typically used. Women with very poor reserve may be counselled about egg donation to improve success rates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','hard','mcq','A 27-year-old woman undergoing IVF develops abdominal bloating, ascites, and oliguria 5 days after egg retrieval. Beta-hCG is positive. What complication has occurred?','["A. Ovarian hyperstimulation syndrome (OHSS)","B. Ovarian torsion","C. Ectopic pregnancy","D. Pelvic haematoma"]','A','Severe OHSS is a iatrogenic complication of ovarian stimulation, potentiated by hCG (endogenous from pregnancy or exogenous trigger). Features: bilateral ovarian enlargement, massive ascites/pleural effusion, oliguria, haemoconcentration, thromboembolic risk. Positive hCG worsens it. Management: IV albumin, prophylactic LMWH, cabergoline (dopamine agonist reduces VEGF), and paracentesis if severe.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','easy','mcq','Which hormone test on day 2–4 of the menstrual cycle provides the best assessment of ovarian reserve?','["A. LH","B. Oestradiol","C. FSH","D. Progesterone"]','C','Day 2–4 FSH is a classic measure of ovarian reserve. Elevated FSH (>10–15 IU/L) indicates diminished ovarian reserve, as the pituitary compensates with increased FSH output to drive failing ovarian follicles. However, AMH and AFC are now preferred as they are more consistent across the cycle. Day 21 (luteal phase) progesterone confirms ovulation (>30 nmol/L suggests adequate ovulation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','mcq','A 32-year-old woman is found to have non-obstructive azoospermia (NOA) with elevated FSH. His partner is 30 with normal fertility tests. What is the next step in their management?','["A. Karyotype and Y-chromosome microdeletion analysis, then consider surgical sperm retrieval (mTESE)","B. Donor sperm insemination directly","C. Clomiphene citrate for 6 months","D. Testosterone supplementation to boost sperm production"]','A','NOA with elevated FSH indicates primary testicular failure. Investigation includes karyotype (Klinefelter 47,XXY is common) and Y-chromosome microdeletion testing (AZFa, AZFb, AZFc). AZFa/b deletions are associated with no sperm recovery; AZFc deletions may allow successful sperm retrieval by microsurgical testicular sperm extraction (mTESE) for ICSI. Testosterone therapy worsens azoospermia by suppressing FSH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','mcq','A 29-year-old woman with PCOS and anovulatory infertility has failed to ovulate on clomiphene citrate after 6 cycles. What is the next ovulation induction option?','["A. Medroxyprogesterone acetate 10 mg for 10 days","B. Letrozole or gonadotrophins (FSH injections)","C. GnRH analogues alone","D. Metformin as sole agent"]','B','After failed clomiphene citrate (6 ovulatory cycles without conception, or failure to ovulate), next options are: letrozole (aromatase inhibitor — now preferred over clomiphene in PCOS due to better live birth rates in NEJM 2014 PPCOS II trial) or exogenous gonadotrophins (FSH injections) with careful monitoring to avoid multiple pregnancy and OHSS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','hard','mcq','A couple have been trying for pregnancy for 2 years. Investigations show bilateral hydrosalpinges on HSG. Their doctor recommends bilateral salpingectomy before IVF. Why?','["A. To prevent ectopic pregnancy only","B. Hydrosalpinx fluid is embryotoxic and reduces IVF implantation rates by 50%; salpingectomy improves IVF success","C. To reduce infection risk during egg retrieval","D. Salpingectomy is not indicated before IVF"]','B','Hydrosalpinx causes a significant reduction in IVF implantation rates (~50%) and pregnancy rates. The proposed mechanism is reflux of the hydrosalpinx fluid (containing endotoxins and prostaglandins) into the uterine cavity, which is embryotoxic and impairs endometrial receptivity. Cochrane review shows bilateral salpingectomy (or proximal tubal occlusion) before IVF significantly improves live birth rates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
